import math
from fractions import Fraction

def solve_quadratic(k1, k2, k3):
    """Solves k1 + k2*p + k3*p^2 = 0 for p."""
    # Rearrange to k3*p^2 + k2*p + k1 = 0

    # Check for valid quadratic form (k3 != 0 is guaranteed by the loop constraints, but good practice)
    if k3 == 0:
        return []

    # Calculate discriminant D = k2^2 - 4*k3*k1
    D = k2*k2 - 4*k3*k1

    if D < 0:
        return []

    sqrt_D = math.sqrt(D)

    # Check if D is a perfect square
    if sqrt_D != int(sqrt_D):
        return []

    sqrt_D_int = int(sqrt_D)

    solutions = set()

    # Solution 1
    numerator1 = -k2 + sqrt_D_int
    denominator = 2 * k3

    # Check if solution is rational (it is, since D is a perfect square) and positive
    if denominator != 0 and numerator1 / denominator > 0:
        solutions.add(Fraction(numerator1, denominator))

    # Solution 2
    numerator2 = -k2 - sqrt_D_int
    if denominator != 0 and numerator2 / denominator > 0:
        solutions.add(Fraction(numerator2, denominator))

    return list(solutions)

def systematic_search():
    possible_p_values = set()

    # Coefficients k1, k2, k3 range from -2 to 2
    for k1 in range(-2, 3):
        for k2 in range(-2, 3):
            for k3 in range(-2, 3):
                if k3 == 0:
                    continue

                solutions = solve_quadratic(k1, k2, k3)
                for p in solutions:
                    possible_p_values.add(p)

    return sorted([str(p) for p in possible_p_values])

print(systematic_search())
